const { createHmac } = require('crypto');
const path = '/internal/calendar/reconciliation/claim';
const body = {};
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const { createHmac } = require('crypto');
const path = '/internal/calendar/provider/changes';
const checkpoint = $json.pageToken || $json.syncToken || 'full-resync';
const body = { connectionId: $json.connectionId, checkpoint };
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const job = $('Split Reconciliation Jobs').item.json;
const payload = $json.body ?? $json;
const page = typeof payload === 'string' ? JSON.parse(payload) : payload;
const commands = [];
if (page.resetRequired) commands.push({ operationId: `${job.operationId}:reset`, tenantId: job.tenantId, ownerId: job.ownerId, connectionId: job.connectionId, kind: 'sync_token_gone' });
for (const event of (page.events || [])) {
  const base = { operationId: `${job.operationId}:event:${event.id}:${event.etag}`, tenantId: job.tenantId, ownerId: job.ownerId, connectionId: job.connectionId, providerEventId: event.id, providerEtag: event.etag };
  if (event.status === 'cancelled') commands.push({ ...base, kind: 'event_deleted' });
  else if (event.start && event.start.dateTime) commands.push({ ...base, kind: 'event_changed', title: event.summary || '', dueAt: event.start.dateTime, timeZone: event.start.timeZone || 'UTC' });
}
const token = page.nextPageToken || page.nextSyncToken;
if (token) commands.push({ operationId: `${job.operationId}:checkpoint:${token}`, tenantId: job.tenantId, ownerId: job.ownerId, connectionId: job.connectionId, kind: 'sync_checkpoint', ...(page.nextPageToken ? { nextPageToken: page.nextPageToken } : {}), ...(page.nextSyncToken ? { nextSyncToken: page.nextSyncToken } : {}) });
return commands.map(command => ({ json: { command } }));

